bool DataBase::insert(uint64_t index,qint64 timestamp,const CUAVInput *data)
{
    QSqlQuery query( m_db);
    QByteArray binary = QByteArray::fromRawData(reinterpret_cast<const char*>(data),sizeof(*data));

    query.prepare("INSERT INTO uavdata(id, timestamp, data) "
                  "VALUES (?, ?, ?)");
    query.addBindValue(index);
    query.addBindValue(timestamp);
    query.addBindValue(binary.toBase64());

    qDebug() << "database insert:" << query.exec() <<"base64:"<< binary.toBase64();

    return true;
}

